import { MakeLogicType, afterMount, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { conversationsSigningSecretRetrieve, conversationsSigningSecretRotateCreate } from '../../generated/api'
import type { SigningSecretApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface signingSecretLogicValues {
    currentTeamId: number | null // teamLogic
    signingSecret: SigningSecretApi | null
    signingSecretLoadFailed: boolean
    signingSecretLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface signingSecretLogicActions {
    loadSigningSecret: () => any
    loadSigningSecretFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSigningSecretSuccess: (
        signingSecret: SigningSecretApi,
        payload?: any
    ) => {
        signingSecret: SigningSecretApi
        payload?: any
    }
    rotateSigningSecret: () => any
    rotateSigningSecretFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    rotateSigningSecretSuccess: (
        signingSecret: SigningSecretApi,
        payload?: any
    ) => {
        signingSecret: SigningSecretApi
        payload?: any
    }
}

export type signingSecretLogicType = MakeLogicType<signingSecretLogicValues, signingSecretLogicActions>

export const signingSecretLogic = kea<signingSecretLogicType>([
    path(['products', 'conversations', 'frontend', 'scenes', 'settings', 'signingSecretLogic']),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    loaders(({ values }) => ({
        signingSecret: [
            null as SigningSecretApi | null,
            {
                loadSigningSecret: async () => await conversationsSigningSecretRetrieve(String(values.currentTeamId)),
                rotateSigningSecret: async () =>
                    await conversationsSigningSecretRotateCreate(String(values.currentTeamId)),
            },
        ],
    })),
    reducers({
        // A failed fetch must not render as "no secret yet": generating from that state
        // would rotate an existing secret without the cutoff warning.
        signingSecretLoadFailed: [
            false,
            {
                loadSigningSecret: () => false,
                loadSigningSecretSuccess: () => false,
                loadSigningSecretFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadSigningSecret()
    }),
])
